MAKE CODE: Blink without delay
language arduino
const int ledPin = 13;
unsigned long last = 0;
bool on = false;

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  if (millis() - last >= 500) {
    last = millis();
    on = !on;
    digitalWrite(ledPin, on ? HIGH : LOW);
  }
}
END

MAKE CODE: Stepper forward and back
language arduino
#include <AccelStepper.h>

AccelStepper stepper(AccelStepper::DRIVER, 3, 2);   // STEP 3, DIR 2

void setup() {
  stepper.setMaxSpeed(1000);
  stepper.setAcceleration(500);
  stepper.moveTo(800);
}

void loop() {
  if (stepper.distanceToGo() == 0) {
    stepper.moveTo(stepper.currentPosition() == 0 ? 800 : 0);
  }
  stepper.run();
}
END

MAKE CODE: P1AM start/stop
language arduino
#include <P1AM.h>

bool running = false;

void setup() {
  while (!P1.init()) {
    ;   // wait for the modules
  }
}

void loop() {
  bool start = P1.readDiscrete(1, 1);
  bool stopOk = P1.readDiscrete(1, 2);   // NC: on while not pressed
  running = (start || running) && stopOk;
  P1.writeDiscrete(running, 2, 1);
}
END

MAKE CODE: Average temperature
language python
import csv


def main():
    temps = []
    with open("readings.csv", newline="") as f:
        for row in csv.DictReader(f):
            temps.append(float(row["temp"]))
    if temps:
        print("Average temp:", sum(temps) / len(temps))
    else:
        print("No readings")


if __name__ == "__main__":
    main()
END

