MAKE CODE: Button lights the LED
language arduino
const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  // with the pull-up, a pressed button reads LOW
  if (digitalRead(buttonPin) == LOW) {
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
}
END

MAKE CODE: Servo sweep
language arduino
#include <Servo.h>

Servo arm;

void setup() {
  arm.attach(9);
}

void loop() {
  for (int a = 0; a <= 180; a++) {
    arm.write(a);
    delay(15);
  }
  for (int a = 180; a >= 0; a--) {
    arm.write(a);
    delay(15);
  }
}
END

MAKE CODE: Tank pump
language arduino
#include <P1AM.h>

bool pumping = false;

void setup() {
  while (!P1.init()) {
    ;   // wait for the modules
  }
}

void loop() {
  bool lowFloat = P1.readDiscrete(1, 1);    // on when the level is low
  bool highFloat = P1.readDiscrete(1, 2);   // on when the tank is full
  if (lowFloat) pumping = true;
  if (highFloat) pumping = false;
  P1.writeDiscrete(pumping, 2, 1);
}
END

