MAKE CODE: Pump for 10 seconds
language st
PROGRAM PumpTimer
VAR
    StartButton AT %IX0.0 : BOOL;
    Pump AT %QX0.0 : BOOL;
END_VAR
VAR
    RunTimer : TP;
END_VAR

RunTimer(IN := StartButton, PT := T#10s);
Pump := RunTimer.Q;
END_PROGRAM
END

